-- ============================== Copy ====================================

function IdolLive3D_IKGroup:CopyFrom_All( src_ )
    IdolLive3D_IKGroup.Copy_Body( src_.Body, self.Body )
    IdolLive3D_IKGroup.Copy_Arm( src_.LeftArm, self.LeftArm )
    IdolLive3D_IKGroup.Copy_Arm( src_.RightArm, self.RightArm )
    IdolLive3D_IKGroup.Copy_Leg( src_.LeftLeg, self.LeftLeg )
    IdolLive3D_IKGroup.Copy_Leg( src_.RightLeg, self.RightLeg )
end


function IdolLive3D_IKGroup.Copy_Body( srcBody_, dstBody_ )
    dstBody_.Body_PositionWeight    = srcBody_.Body_PositionWeight
    dstBody_.Mapping_MaintainHeadRot        = srcBody_.Mapping_MaintainHeadRot
end


function IdolLive3D_IKGroup.Copy_Arm( srcArm_, dstArm_ )
    dstArm_.Hand_PositionWeight         = srcArm_.Hand_PositionWeight
    dstArm_.Hand_RotationWeight         = srcArm_.Hand_RotationWeight
    dstArm_.Hand_MaintainRelativePos    = srcArm_.Hand_MaintainRelativePos
    ---
    dstArm_.Shoulder_PositionWeight = srcArm_.Shoulder_PositionWeight
    ---     
    dstArm_.Elbow_GoalWeight = srcArm_.Elbow_GoalWeight
    ---
    dstArm_.Mapping_MappingWeight   = srcArm_.Mapping_MappingWeight
    dstArm_.Mapping_MaintainHandRot = srcArm_.Mapping_MaintainHandRot
end


function IdolLive3D_IKGroup.Copy_Leg( srcLeg_, dstLeg_ )
    dstLeg_.Foot_PositionWeight = srcLeg_.Foot_PositionWeight
    dstLeg_.Foot_RotationWeight = srcLeg_.Foot_RotationWeight
    dstLeg_.Foot_MaintainRelativePos = srcLeg_.Foot_MaintainRelativePos
    ---
    dstLeg_.Thigh_PositionWeight = srcLeg_.Thigh_PositionWeight
    ---     
    dstLeg_.Knee_GoalWeight = srcLeg_.Knee_GoalWeight
    ---
    dstLeg_.Mapping_MappingWeight = srcLeg_.Mapping_MappingWeight
    dstLeg_.Mapping_MaintainFootRot = srcLeg_.Mapping_MaintainFootRot
end



