-- ============================== Lerp ====================================

---@return boolean @ 是否足够接近
function IdolLive3D_IKGroup.Lerp_Body( beBody_, tgtBody_, w_ )
    beBody_.Body_PositionWeight     = Mathf.Lerp( beBody_.Body_PositionWeight,      tgtBody_.Body_PositionWeight, w_ )
    beBody_.Mapping_MaintainHeadRot = Mathf.Lerp( beBody_.Mapping_MaintainHeadRot,  tgtBody_.Mapping_MaintainHeadRot,     w_ )
    ---
    return  (IdolLive3D_Utils.CloseEnough(beBody_.Body_PositionWeight,       tgtBody_.Body_PositionWeight,      0.0001) and 
             IdolLive3D_Utils.CloseEnough(beBody_.Mapping_MaintainHeadRot,   tgtBody_.Mapping_MaintainHeadRot,  0.0001) )
end

---@return boolean @ 是否足够接近
function IdolLive3D_IKGroup.Lerp_Arm( beArm_, tgtArm_, w_ )
    beArm_.Hand_PositionWeight      = Mathf.Lerp( beArm_.Hand_PositionWeight,       tgtArm_.Hand_PositionWeight,        w_ )
    beArm_.Hand_RotationWeight      = Mathf.Lerp( beArm_.Hand_RotationWeight,       tgtArm_.Hand_RotationWeight,        w_ )
    beArm_.Hand_MaintainRelativePos = Mathf.Lerp( beArm_.Hand_MaintainRelativePos,  tgtArm_.Hand_MaintainRelativePos,   w_ )
    ---
    beArm_.Shoulder_PositionWeight = Mathf.Lerp( beArm_.Shoulder_PositionWeight, tgtArm_.Shoulder_PositionWeight, w_ ) 
    ---
    beArm_.Elbow_GoalWeight = Mathf.Lerp( beArm_.Elbow_GoalWeight, tgtArm_.Elbow_GoalWeight, w_ )
    ---
    beArm_.Mapping_MappingWeight    = Mathf.Lerp( beArm_.Mapping_MappingWeight,     tgtArm_.Mapping_MappingWeight,   w_ )
    beArm_.Mapping_MaintainHandRot  = Mathf.Lerp( beArm_.Mapping_MaintainHandRot,   tgtArm_.Mapping_MaintainHandRot, w_ )
    ---
    return  (IdolLive3D_Utils.CloseEnough( beArm_.Hand_PositionWeight,      tgtArm_.Hand_PositionWeight,        0.0001) and 
             IdolLive3D_Utils.CloseEnough( beArm_.Hand_RotationWeight,      tgtArm_.Hand_RotationWeight,        0.0001) and
             IdolLive3D_Utils.CloseEnough( beArm_.Hand_MaintainRelativePos, tgtArm_.Hand_MaintainRelativePos,   0.0001) and 
             IdolLive3D_Utils.CloseEnough( beArm_.Shoulder_PositionWeight,  tgtArm_.Shoulder_PositionWeight,    0.0001) and
             IdolLive3D_Utils.CloseEnough( beArm_.Elbow_GoalWeight,         tgtArm_.Elbow_GoalWeight,           0.0001) and
             IdolLive3D_Utils.CloseEnough( beArm_.Mapping_MappingWeight,    tgtArm_.Mapping_MappingWeight,      0.0001) and 
             IdolLive3D_Utils.CloseEnough( beArm_.Mapping_MaintainHandRot,  tgtArm_.Mapping_MaintainHandRot,    0.0001) )
end

---@return boolean @ 是否足够接近
function IdolLive3D_IKGroup.Lerp_Leg( beLeg_, tgtLeg_, w_ )
    beLeg_.Foot_PositionWeight      = Mathf.Lerp( beLeg_.Foot_PositionWeight,       tgtLeg_.Foot_PositionWeight,     w_ )
    beLeg_.Foot_RotationWeight      = Mathf.Lerp( beLeg_.Foot_RotationWeight,       tgtLeg_.Foot_RotationWeight,     w_ )
    beLeg_.Foot_MaintainRelativePos = Mathf.Lerp( beLeg_.Foot_MaintainRelativePos,  tgtLeg_.Foot_MaintainRelativePos, w_ )
    ---
    beLeg_.Thigh_PositionWeight = Mathf.Lerp( beLeg_.Thigh_PositionWeight, tgtLeg_.Thigh_PositionWeight, w_ )
    ---   
    beLeg_.Knee_GoalWeight = Mathf.Lerp( beLeg_.Knee_GoalWeight, tgtLeg_.Knee_GoalWeight, w_ )
    ---
    beLeg_.Mapping_MappingWeight    = Mathf.Lerp( beLeg_.Mapping_MappingWeight,     tgtLeg_.Mapping_MappingWeight,   w_ )
    beLeg_.Mapping_MaintainFootRot  = Mathf.Lerp( beLeg_.Mapping_MaintainFootRot,   tgtLeg_.Mapping_MaintainFootRot, w_ )
    ---
    return  (IdolLive3D_Utils.CloseEnough( beLeg_.Foot_PositionWeight,          tgtLeg_.Foot_PositionWeight,        0.0001) and 
             IdolLive3D_Utils.CloseEnough( beLeg_.Foot_RotationWeight,          tgtLeg_.Foot_RotationWeight,        0.0001) and
             IdolLive3D_Utils.CloseEnough( beLeg_.Foot_MaintainRelativePos,     tgtLeg_.Foot_MaintainRelativePos,   0.0001) and 
             IdolLive3D_Utils.CloseEnough( beLeg_.Thigh_PositionWeight,         tgtLeg_.Thigh_PositionWeight,       0.0001) and
             IdolLive3D_Utils.CloseEnough( beLeg_.Knee_GoalWeight,              tgtLeg_.Knee_GoalWeight,            0.0001) and
             IdolLive3D_Utils.CloseEnough( beLeg_.Mapping_MappingWeight,        tgtLeg_.Mapping_MappingWeight,      0.0001) and 
             IdolLive3D_Utils.CloseEnough( beLeg_.Mapping_MaintainFootRot,      tgtLeg_.Mapping_MaintainFootRot,    0.0001) )
end













